import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

import { describe, expect, it } from "vitest";

import { tuneMetrics } from "../src/compat/index.js";

/**
 * **`tuneMetrics` — EACH MEASURE'S MINIMUM WIDTH.**
 *
 * The oracle is `tests/corpus-tune-metrics/golden.json`, generated by RUNNING abcjs 6.7.0
 * over every fixture of both corpora (`scripts/harvest-abcjs-tune-metrics.mjs`). Every
 * number is compared: each section's `left`, its `measureWidths` and its `total`.
 *
 * The numbers come from a layout at width **0**, where every spring has collapsed and the
 * rods are all that is left — see `tune-metrics.ts` for why that needed no new layout mode,
 * only the staff-width-to-page conversion `renderAbc` already makes.
 *
 * ⚠️ **ONE SLOT, SO ONE TUNE PER FILE**: `tuneMetrics` passes the string `"*"`, which is a
 * single output slot, so a book reports its FIRST tune and nothing else.
 */
type Section = { left: number; measureWidths: number[]; total: number };

const GOLDEN = JSON.parse(
  readFileSync(join(import.meta.dirname, "corpus-tune-metrics", "golden.json"), "utf-8"),
) as Record<string, Section[]>;

const config = JSON.parse(
  readFileSync(join(import.meta.dirname, "..", "abcts.config.json"), "utf-8"),
) as { corpus: string };

const DIRS: Record<string, string> = {
  repo: join(import.meta.dirname, "corpus-abcjs", "fixtures"),
  sib: join(import.meta.dirname, "..", config.corpus),
};

const ours = (key: string): Section[] => {
  const [corpus = "", rest = ""] = key.split("/");
  const file = rest.substring(0, rest.lastIndexOf("-tune"));
  const abc = readFileSync(join(DIRS[corpus] ?? "", `${file}.abc`), "utf-8");
  return tuneMetrics(abc, {})[0]?.sections ?? [];
};

interface Row {
  readonly slug: string;
  readonly agree: number;
  readonly total: number;
  readonly first: string;
}

const table = (): Row[] =>
  Object.entries(GOLDEN).map(([slug, want]) => {
    const got = ours(slug);
    let agree = 0;
    let first = "";
    for (let i = 0; i < Math.max(want.length, got.length); i += 1) {
      if (JSON.stringify(want[i]) === JSON.stringify(got[i])) agree += 1;
      else if (first === "")
        first = `section ${i}: abcjs ${JSON.stringify(want[i])?.slice(0, 150)} ours ${JSON.stringify(got[i])?.slice(0, 150)}`;
    }
    return { slug, agree, total: want.length, first };
  });

