describe("tuneMetrics — each measure's minimum width", () => {
  const rows = table();

  it("writes the ranked table", () => {
    const off = rows.filter((r) => r.agree < r.total);
    const agree = rows.reduce((t, r) => t + r.agree, 0);
    const total = rows.reduce((t, r) => t + r.total, 0);
    writeFileSync(
      "/tmp/abcts-tune-metrics-ranked.txt",
      `${[
        `${off.length} of ${rows.length} tunes differ; ${agree} of ${total} sections agree`,
        "",
        ...off.map((r) => `  ${r.slug.padEnd(54)} ${r.agree}/${r.total}  ${r.first}`),
      ].join("\n")}\n`,
    );
    expect(rows.length).toBeGreaterThan(200);
  });

  it("every ratcheted tune agrees on every section", () => {
    const broken = rows
      .filter((r) => PASSING.includes(r.slug) && r.agree < r.total)
      .map((r) => `${r.slug} ${r.agree}/${r.total} ${r.first}`);
    expect(broken.slice(0, 10)).toEqual([]);
  });

  it("nothing outside the ratchet has quietly started agreeing", () => {
    const arrived = rows
      .filter((r) => !PASSING.includes(r.slug) && r.agree === r.total)
      .map((r) => r.slug);
    expect(arrived.length, `${arrived.length} tunes agree — re-ratchet`).toBe(0);
  });
});
